import sys

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)

    def add(self, idx, delta):
        n = self.n
        bit = self.bit
        while idx <= n:
            bit[idx] += delta
            idx += idx & -idx

    def kth(self, k):
        idx = 0
        step = 1 << (self.n.bit_length() - 1)
        bit = self.bit
        while step:
            nxt = idx + step
            if nxt <= self.n and bit[nxt] < k:
                idx = nxt
                k -= bit[nxt]
            step >>= 1
        return idx + 1

def main():
    input = sys.stdin.readline
    N = int(input())
    P = list(map(int, input().split()))

    fw = Fenwick(N)
    for i in range(1, N + 1):
        fw.add(i, 1)

    ans = [0] * N
    for value in range(N, 0, -1):
        pos = fw.kth(P[value - 1])
        ans[pos - 1] = value
        fw.add(pos, -1)

    print(*ans)

if __name__ == "__main__":
    main()
